#!/usr/bin/env python3
"""Build the canonical merged topic sequence and sync it into index.html.

Why this exists
---------------
The tracker keeps two parallel inventories:
  * DATA.topics  — per-paper topic rows (CS and DA), keyed "exam+subject+topic".
                   Shared topics appear twice and are linked by a reciprocal
                   `twin` field so a tick mirrors to the other paper.
  * DATA.checklist — the Master Checklist (generated by checklist_data_make.py).

The Topics pane used to render DATA.topics grouped by "subject|exam", sorted
alphabetically, which meant the study order was lost and shared topics showed
up twice, far apart. The plan in 03_Schedule_Plans.md and the README both call
for "everything shared gets studied exactly once", in a fixed sequence.

This script therefore:
  1. Applies research corrections against the official GATE 2027 syllabus
     (https://gate2027.iitm.ac.in/static/doc/GATE2027_Syllabus/):
       - DA Section 4 is "Programming in Python" — the DA programming rows were
         carrying C-only topics (pointers, structs/unions, operator precedence),
         which do not exist in the DA paper. Replaced with Python equivalents.
       - DA Section 2 names "idempotent matrix" and "partition matrix" — both
         were missing from Linear Algebra.
       - General Aptitude is a paper-wide section (10 questions / 15 marks) that
         the plan schedules and the Master Checklist tracks, but which had no
         rows in DATA.topics at all.
  2. Builds DATA.sequence: every topic exactly once, merged across papers,
     ordered by the plan's phase sequence (Phase 1 shared spine -> Phase 2
     CS-only paired with DA-only).
  3. Writes DATA back into index.html.

Idempotent: re-running produces the same output. It refuses to write if any
topic would fall out of the sequence.

Usage:  python sequence_data_make.py
"""
import json
import re
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
INDEX = HERE / "index.html"

P1 = "Phase 1 – Fundamentals"
P2 = "Phase 2 – Full Syllabus"

# ---------------------------------------------------------------------------
# Research corrections
# ---------------------------------------------------------------------------

# DA Section 4 of the official syllabus is "Programming in Python". The DA
# paper never tests C. These rows replace the C-only rows.
DA_C_ROWS = [
    "C programming fundamentals",
    "Operators and expression evaluation",
    "Control flow and loops",
    "Functions and parameter passing",
    "Pointers and pointer arithmetic",
    "Arrays and strings",
    "Structures and unions",
    "Recursion and call stack",
]
DA_PY_ROWS = [
    ("Python fundamentals and types", 1),
    ("Python expressions, operators and evaluation order", 1),
    ("Python control flow, loops and comprehensions", 1),
    ("Python functions, arguments and closures", 1),
    ("Python strings, lists and tuples", 1),
    ("Python dictionaries and sets", 1),
    ("Recursion and output tracing in Python", 1),
]
# Progress recorded against the old C-only DA rows carries over to the Python
# rows that replace them. Two old rows may collapse onto one new row.
DA_C_TO_PY = {
    "C programming fundamentals": "Python fundamentals and types",
    "Operators and expression evaluation": "Python expressions, operators and evaluation order",
    "Control flow and loops": "Python control flow, loops and comprehensions",
    "Functions and parameter passing": "Python functions, arguments and closures",
    "Pointers and pointer arithmetic": "Python dictionaries and sets",
    "Arrays and strings": "Python strings, lists and tuples",
    "Structures and unions": "Python dictionaries and sets",
    "Recursion and call stack": "Recursion and output tracing in Python",
}
DA_PROG_SUBJECT = "Programming and Data Structures and Algorithms"
CS_PROG_SUBJECT = "Programming and Data Structures"

# DA Section 2 names these explicitly; the checklist covers them as subtopics
# but DATA.topics had no rows for them.
LA_ADDITIONS = [("Idempotent matrix", 2), ("Partition matrix", 2)]

# General Aptitude — common section, 10 questions / 15 marks, both papers.
GA_ROWS = [
    ("Verbal ability and reading comprehension", 1),
    ("Quantitative aptitude and data interpretation", 1),
    ("Logical reasoning and analytical ability", 1),
    ("Spatial ability and pattern reasoning", 1),
]
GA_SUBJECT = "General Aptitude"

# ---------------------------------------------------------------------------
# Canonical sequence: (phase, label, [CS subjects], [DA subjects])
# Order follows the weekly goals in DATA.weekly / 03_Schedule_Plans.md.
# ---------------------------------------------------------------------------
BLOCKS = [
    (P1, "Linear Algebra", ["Linear Algebra"], ["Linear Algebra"]),
    (P1, "Probability and Statistics", ["Probability and Statistics"], ["Probability and Statistics"]),
    (P1, "Calculus and Optimization", ["Calculus"], ["Calculus"]),
    (P1, "Discrete Mathematics", ["Discrete Mathematics"], []),
    (P1, "Programming, Data Structures and Algorithms", [CS_PROG_SUBJECT], [DA_PROG_SUBJECT]),
    (P1, "Algorithms", ["Algorithms"], []),
    (P1, "Database Management and Warehousing", ["Database Management Systems"], ["Database Management and Warehousing"]),
    (P1, "General Aptitude", [GA_SUBJECT], [GA_SUBJECT]),
    (P2, "Theory of Computation", ["Theory of Computation"], []),
    (P2, "Machine Learning", [], ["Machine Learning"]),
    (P2, "Operating Systems", ["Operating Systems"], []),
    (P2, "Computer Organization and Architecture", ["Computer Organization and Architecture"], []),
    (P2, "Digital Logic", ["Digital Logic"], []),
    (P2, "Artificial Intelligence", [], ["Artificial Intelligence"]),
    (P2, "Computer Networks", ["Computer Networks"], []),
    (P2, "Compiler Design", ["Compiler Design"], []),
]

# Optional notes shown under a block in the Topics pane.
NOTES = {
    "General Aptitude": "one practice track - 15 marks on both papers; the plan runs a "
                        "30-minute aptitude block every day from week 1",
    "Programming, Data Structures and Algorithms":
        "shared concepts once - the CS paper traces C, the DA paper traces Python",
}


def tkey(t):
    return t["exam"] + t["subject"] + (t.get("topic") or "")


def load_data():
    text = INDEX.read_text(encoding="utf-8")
    m = re.search(r"^const DATA = (\{.*\});$", text, re.M)
    if not m:
        sys.exit("ABORT: could not locate the `const DATA = {...};` line in index.html")
    return text, m, json.loads(m.group(1))


def save_data(text, m, data):
    new_line = "const DATA = " + json.dumps(data, ensure_ascii=False, separators=(",", ":")) + ";"
    out = text[: m.start()] + new_line + text[m.end():]
    INDEX.write_text(out, encoding="utf-8", newline="")
    return out


def apply_topic_fixes(topics):
    """Returns (topics, migrations). Idempotent."""
    migrations = []
    by = {tkey(t): t for t in topics}

    # -- DA programming: C rows -> Python rows -----------------------------
    da_prog = [t for t in topics if t["exam"] == "DA" and t["subject"] == DA_PROG_SUBJECT]
    have_python = any(t["topic"] == DA_PY_ROWS[0][0] for t in da_prog)
    if not have_python:
        if not da_prog:
            sys.exit("ABORT: no DA programming rows found")
        idx = topics.index(da_prog[0])
        # drop the 8 C-only rows
        for name in DA_C_ROWS:
            row = next((t for t in da_prog if t["topic"] == name), None)
            if row is None:
                sys.exit("ABORT: expected DA C row not found: %s" % name)
            topics.remove(row)
            # the CS side loses its twin: DA no longer teaches C
            cs_twin = next((t for t in topics if t.get("twin") == tkey(row)), None)
            if cs_twin is not None:
                cs_twin.pop("twin", None)
        # insert the Python rows at the same position
        for offset, (name, tier) in enumerate(DA_PY_ROWS):
            topics.insert(idx + offset, {
                "exam": "DA", "subject": DA_PROG_SUBJECT, "topic": name, "tier": tier,
            })

    # The migration map is emitted unconditionally so the generator is
    # idempotent: re-running on an already-converted file still records it.
    # Old keys simply do not exist in a fresh store, which is harmless.
    for old_name, new_name in DA_C_TO_PY.items():
        migrations.append([
            "DA" + DA_PROG_SUBJECT + old_name,
            "DA" + DA_PROG_SUBJECT + new_name,
        ])

    # -- Linear Algebra: idempotent + partition matrix ---------------------
    for name, tier in LA_ADDITIONS:
        if not any(t["topic"] == name for t in topics):
            for exam in ("CS", "DA"):
                anchor = next(
                    (t for t in topics
                     if t["exam"] == exam and t["subject"] == "Linear Algebra"
                     and t["topic"] == "Quadratic forms"),
                    None,
                )
                if anchor is None:
                    sys.exit("ABORT: Linear Algebra anchor not found for %s" % name)
                topics.insert(topics.index(anchor), {
                    "exam": exam, "subject": "Linear Algebra", "topic": name, "tier": tier,
                })
            # reciprocal twin link
            cs = next(t for t in topics
                      if t["exam"] == "CS" and t["subject"] == "Linear Algebra" and t["topic"] == name)
            da = next(t for t in topics
                      if t["exam"] == "DA" and t["subject"] == "Linear Algebra" and t["topic"] == name)
            cs["twin"] = tkey(da)
            da["twin"] = tkey(cs)

    # -- General Aptitude --------------------------------------------------
    if not any(t["subject"] == GA_SUBJECT for t in topics):
        for name, tier in GA_ROWS:
            cs = {"exam": "CS", "subject": GA_SUBJECT, "topic": name, "tier": tier}
            da = {"exam": "DA", "subject": GA_SUBJECT, "topic": name, "tier": tier}
            cs["twin"] = tkey(da)
            da["twin"] = tkey(cs)
            topics.append(cs)
            topics.append(da)

    return topics, migrations


def build_sequence(topics):
    """Merged, phase-ordered sequence. Every topic appears exactly once."""
    by_key = {tkey(t): t for t in topics}
    twin_of = {tkey(t): t.get("twin") for t in topics}

    cs_subject_block = {}
    for i, (_ph, _lb, cs_subs, _da) in enumerate(BLOCKS):
        for s in cs_subs:
            cs_subject_block[s] = i

    # which block does a DA topic belong to? follow its twin's CS subject
    def da_block(da_topic, fallback):
        tw = twin_of.get(tkey(da_topic))
        if tw:
            tw_row = by_key.get(tw)
            if tw_row and tw_row["exam"] == "CS" and tw_row["subject"] in cs_subject_block:
                return cs_subject_block[tw_row["subject"]]
        return fallback

    # gather per block
    block_cs = {i: [] for i in range(len(BLOCKS))}
    block_da = {i: [] for i in range(len(BLOCKS))}
    for t in topics:
        if t["exam"] == "CS":
            b = cs_subject_block.get(t["subject"])
            if b is None:
                sys.exit("ABORT: CS subject not in any sequence block: %s" % t["subject"])
            block_cs[b].append(t)
        else:
            placed = False
            for i, (_ph, _lb, _cs, da_subs) in enumerate(BLOCKS):
                if t["subject"] in da_subs:
                    b = da_block(t, i)
                    block_da[b].append(t)
                    placed = True
                    break
            if not placed:
                sys.exit("ABORT: DA subject not in any sequence block: %s" % t["subject"])

    sequence = []
    seen = set()
    for i, (phase, label, cs_subs, da_subs) in enumerate(BLOCKS):
        cs_list = block_cs[i]
        da_list = block_da[i]
        da_keys = {tkey(t) for t in da_list}
        cs_keys = {tkey(t) for t in cs_list}
        rows = []
        used_da = set()

        for ct in cs_list:
            ck = tkey(ct)
            seen.add(ck)
            row = {"t": ct["topic"], "c": ck, "y": ct["tier"]}
            tw = twin_of.get(ck)
            if tw and tw in da_keys:
                row["d"] = tw
                used_da.add(tw)
                seen.add(tw)
            rows.append(row)

        for dt in da_list:
            dk = tkey(dt)
            if dk in used_da:
                continue
            seen.add(dk)
            rows.append({"t": dt["topic"], "d": dk, "y": dt["tier"]})

        if not rows:
            sys.exit("ABORT: sequence block %r has no rows" % label)
        block = {"phase": phase, "label": label, "rows": rows}
        if label in NOTES:
            block["note"] = NOTES[label]
        sequence.append(block)

    missing = [tkey(t) for t in topics if tkey(t) not in seen]
    if missing:
        sys.exit("ABORT: %d topics would be dropped from the sequence:\n  %s"
                 % (len(missing), "\n  ".join(missing[:20])))
    return sequence


def main():
    text, m, data = load_data()
    data["topics"], migrations = apply_topic_fixes(data["topics"])
    data["sequence"] = build_sequence(data["topics"])
    data["topicMigrations"] = migrations
    save_data(text, m, data)

    rows = sum(len(b["rows"]) for b in data["sequence"])
    print("topics          : %d (CS %d / DA %d)" % (
        len(data["topics"]),
        sum(1 for t in data["topics"] if t["exam"] == "CS"),
        sum(1 for t in data["topics"] if t["exam"] == "DA")))
    print("sequence blocks : %d" % len(data["sequence"]))
    print("sequence rows   : %d  (each row = one study unit, shared topics merged)" % rows)
    print("migrations      : %d" % len(migrations))
    for b in data["sequence"]:
        both = sum(1 for r in b["rows"] if "c" in r and "d" in r)
        conly = sum(1 for r in b["rows"] if "c" in r and "d" not in r)
        donly = sum(1 for r in b["rows"] if "d" in r and "c" not in r)
        print("  %-34s %3d rows  (%d shared, %d CS-only, %d DA-only)"
              % (b["label"], len(b["rows"]), both, conly, donly))


if __name__ == "__main__":
    main()
